CREATE DATABASE IF NOT EXISTS fsp_db;

USE fsp_db;

CREATE TABLE fsp_compras_si (
    ident_version INT(5) NOT NULL,
    ident_ambiente INT(5) NOT NULL,
    ident_tipoDte INT(5) NOT NULL,
    ident_numeroControl CHAR(32) NOT NULL,
    ident_codigoGeneracion CHAR(40) NOT NULL,
    ident_tipoModelo INT(5) NOT NULL,
    ident_tipoOperacion INT(5) NOT NULL,
