    ident_fecEmi VARCHAR(10) NOT NULL,
    ident_horEmi VARCHAR(8) NOT NULL,
    ident_tipoMoneda CHAR(10) NOT NULL,
    dr_tipoDocumento INT(5) NOT NULL,
    dr_tipoGeneracion INT(5) NOT NULL,
    dr_numeroDocumento CHAR(32) NOT NULL,
    dr_fechaEmision VARCHAR(10) NOT NULL,
    emisor_nit CHAR(14) NOT NULL,
    emisor_nrc INT(10) NOT NULL,
    emisor_nombre TEXT(100) NOT NULL,
    emisor_codActividad INT(10) NOT NULL,
    emisor_descActividad TEXT(200) NOT NULL,
    emisor_nombreComercial TEXT(100) NOT NULL,
    emisor_tipoEstablecimiento INT(5) NOT NULL,
    emisor_dir_departamento INT(5) NOT NULL,
    emisor_dir_municipio INT(5) NOT NULL,
    emisor_dir_complemento TEXT(500) NOT NULL,
    emisor_telefono CHAR(50) NOT NULL,
    emisor_correo VARCHAR(100) NOT NULL,
    emisor_codEstableMH CHAR(10) NOT NULL,
    emisor_codEstable CHAR(10) NOT NULL,
    emisor_codPuntoVentaMH CHAR(10) NOT NULL,
    emisor_codPuntoVenta CHAR(10) NOT NULL,
    receptor_nit CHAR(14) NOT NULL,
    receptor_nrc INT(10) NOT NULL,
    receptor_nombre TEXT(50) NOT NULL,
    receptor_codActividad INT(10) NOT NULL,
    receptor_descActividad TEXT(60) NOT NULL,
    receptor_nombreComercial CHAR(50) NOT NULL,
    receptor_dir_departamento INT(5) NOT NULL,
    receptor_dir_municipio INT(5) NOT NULL,
    receptor_dir_complemento TEXT(500) NOT NULL,
    receptor_telefono CHAR(50) NOT NULL,
    receptor_correo VARCHAR(100) NOT NULL,
    f_cuerpoDoc_numItem INT(5) NOT NULL,
    f_cuerpoDoc_tipoItem INT(5) NOT NULL,
    f_cuerpoDoc_numeroDocumento VARCHAR(40) NOT NULL,
    f_cuerpoDoc_cantidad DECIMAL(10,4) NOT NULL,
    f_cuerpoDoc_codigo INT(10) NOT NULL,
    f_cuerpoDoc_codTributo VARCHAR(40) NOT NULL,
    f_cuerpoDoc_uniMedida INT(5) NOT NULL,
    f_cuerpoDoc_descripcion TEXT(100) NOT NULL,
    f_cuerpoDoc_precioUni DECIMAL(10,4) NOT NULL,
    f_cuerpoDoc_montoDescu DECIMAL(10,4) NOT NULL,
    f_cuerpoDoc_ventaNoSuj DECIMAL(10,4) NOT NULL,
    f_cuerpoDoc_ventaExenta DECIMAL(10,4) NOT NULL,
    f_cuerpoDoc_ventaGravada DECIMAL(10,4) NOT NULL,
    f_cuerpoDoc_t_tributos INT(5) NOT NULL,
    f_cuerpoDoc_psv DECIMAL(10,4) NOT NULL,
    f_cuerpoDoc_noGravado DECIMAL(10,4) NOT NULL,
    resumen_totalNoSuj DECIMAL(10,4) NOT NULL,
    resumen_totalExenta DECIMAL(10,4) NOT NULL,
    resumen_totalGravada DECIMAL(10,4) NOT NULL,
    resumen_subTotalVentas DECIMAL(10,4) NOT NULL,
    resumen_descuNoSuj DECIMAL(10,4) NOT NULL,
    resumen_descuExenta DECIMAL(10,4) NOT NULL,
    resumen_descuGravada DECIMAL(10,4) NOT NULL,
    resumen_porcentajeDescuento DECIMAL(10,4) NOT NULL,
    resumen_totalDescu DECIMAL(10,4) NOT NULL,
    f_resumen_tributos_codigo DECIMAL(10,4) NOT NULL,
    f_resumen_tributos_descripcion CHAR(100) NOT NULL,
    f_resumen_tributos_valor DECIMAL(10,4) NOT NULL,
    resumen_subTotal DECIMAL(10,4) NOT NULL,
    resumen_ivaPerci1 DECIMAL(10,4) NOT NULL,
    resumen_ivaRete1 DECIMAL(10,4) NOT NULL,
    resumen_reteRenta DECIMAL(10,4) NOT NULL,
    resumen_montoTotalOperacion DECIMAL(10,4) NOT NULL,
    resumen_totalNoGravado DECIMAL(10,4) NOT NULL,
    resumen_totalPagar DECIMAL(10,4) NOT NULL,
    resumen_totalLetras VARCHAR(200) NOT NULL,
    resumen_saldoFavor DECIMAL(10,4) NOT NULL,
    resumen_condicionOperacion INT(5) NOT NULL,
    resumen_pagos VARCHAR(40) NOT NULL,
    resumen_numPagoElectronico INT(5) NOT NULL,
    sr_selloRecibido VARCHAR(1000) NOT NULL 
);

CREATE TABLE productos (
    cod_producto INT PRIMARY KEY,
    nombre_producto VARCHAR(255) NOT NULL,
    descripcion TEXT,
    laboratorio TEXT NOT NULL,
    venta_solo_una_presentacion BOOLEAN DEFAULT FALSE,
    venta_solo_venta_por_caja BOOLEAN DEFAULT FALSE,
    precio_caja DECIMAL(10,2) NOT NULL,
    precio_blister DECIMAL(10,2) NOT NULL,
    precio_unitario DECIMAL(10,2) NOT NULL,
    fecha_registro VARCHAR(50) NOT NULL,
    user_registro VARCHAR(50) NOT NULL,
    activo BOOLEAN DEFAULT TRUE
);

CREATE TABLE inventario (
    cod_inventario INT NOT NULL,
    existencia_total INT NOT NULL,
    cod_producto INT NOT NULL,
    nombre_producto INT NOT NULL,
    laboratorio INT NOT NULL,
    fecha_vencimiento VARCHAR(50) NOT NULL,
    fecha_registro VARCHAR(50) NOT NULL,
    user_registro VARCHAR(50) NOT NULL,
);

CREATE TABLE presentaciones (
    cod_presentación VARCHAR(50) NOT NULL,
    detalle_presentación TEXT,
    cantidad_presentación INT NOT NULL,
    fecha_registro VARCHAR(50) NOT NULL,
    user_registro VARCHAR(50) NOT NULL,
);

CREATE TABLE cod_barra (
    id_cod_barra INT PRIMARY KEY,
    cod_barra_descripcion VARCHAR(50) NOT NULL,
    cod_presentación VARCHAR(50) NOT NULL,
    cod_producto VARCHAR(50) NOT NULL,
    fecha_registro VARCHAR(50) NOT NULL,
    user_registro VARCHAR(50) NOT NULL,
);








